  width: 2rem;
  height: 2rem;
  border-radius: 6px;
  background: var(--accent);
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 700;
  font-size: 0.875rem;
  flex-shrink: 0;
  aria-hidden: true;
}
.site-header__name {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text);
}

/* ── Main ───────────────────────────────────────────── */
main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2.5rem 1rem 3rem;
  gap: 2rem;
}

/* ── Page heading ───────────────────────────────────── */
.page-heading {
  text-align: center;
}
.page-heading h1 {
  font-size: clamp(1.4rem, 4vw, 2rem);
  font-weight: 700;
  color: var(--text);
}
.page-heading p {
  margin-top: 0.4rem;
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ── Image card ─────────────────────────────────────── */
.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
}
.image-card__img-wrap {
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--surface-2);
  overflow: hidden;
}
.image-card__img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.image-card__meta {
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.image-card__info {
  flex: 1;
  min-width: 0;
}
.image-card__title {
  font-weight: 600;
  font-size: 0.9375rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.image-card__subtitle {
  color: var(--text-muted);
  font-size: 0.8125rem;
  margin-top: 0.125rem;
}
.image-card__actions {
  flex-shrink: 0;
}

/* ── Buttons ────────────────────────────────────────── */
button { cursor: pointer; font-family: inherit; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  line-height: 1;
  text-decoration: none;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn--danger {
  background: transparent;
  border-color: var(--danger);
  color: var(--danger);
}
.btn--danger:hover {
  background: rgba(224, 82, 82, 0.12);
}
.btn--danger:active {
  background: rgba(224, 82, 82, 0.2);
}

.btn--ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
}
.btn--ghost:hover {
  background: var(--surface-2);
  border-color: #3e4460;
}

.btn--filled-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn--filled-danger:hover {
  background: var(--danger-dark);
  border-color: var(--danger-dark);
}
.btn--filled-danger:active {
  background: #a83030;
}

/* ── Dialog ─────────────────────────────────────────── */
dialog {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  padding: 0;
  width: min(92vw, 420px);
  box-shadow: var(--shadow-lg);
  /* Closed by default; shown via JS .showModal() */
}
dialog::backdrop {
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(3px);
}

.dialog__header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.5rem 1.5rem 1rem;
}
.dialog__icon {
  flex-shrink: 0;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  background: rgba(224, 82, 82, 0.15);
  display: grid;
  place-items: center;
  color: var(--danger);
}
.dialog__icon svg { display: block; }

.dialog__title {
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.3;
  margin-top: 0.35rem;
}

.dialog__body {
  padding: 0 1.5rem 1.25rem;
  color: var(--text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}
.dialog__body strong {
  color: var(--text);
  font-weight: 500;
}

