*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #0f1117;
  --surface:     #1a1d27;
  --surface-2:   #22263a;
  --border:      #2e3348;
  --text:        #e2e5f1;
  --text-muted:  #8b90a8;
  --accent:      #6c8ef7;
  --accent-dark: #4a6ef5;
  /* --danger is used for outline-button text/border on the dark surface.
     Must be bright enough for 4.5:1 on --surface (#1a1d27): #f06060 ≈ 4.75:1 ✓ */
  --danger:           #f06060;
  /* --danger-filled is used as the background of filled danger buttons.
     White text on this background: 6.0:1 ✓ */
  --danger-filled:    #b83030;
  --danger-dark:      #9a2828;
  --focus-ring:  #6c8ef7;
  --radius:      12px;
  --radius-sm:   8px;
  --shadow-lg:   0 24px 64px rgba(0, 0, 0, 0.65);
  --transition:  150ms ease;
}

/* ── Page ───────────────────────────────────────────── */
body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr auto;
}

/* ── Skip link ──────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0.75rem; }

/* ── Header ─────────────────────────────────────────── */
.site-header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.site-header__logo {
  width: 2rem;
  height: 2rem;
  border-radius: 6px;
  background: var(--accent);
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 700;
  font-size: 0.875rem;
  flex-shrink: 0;
  aria-hidden: true;
}
.site-header__name {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text);
}

/* ── Main ───────────────────────────────────────────── */
main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2.5rem 1rem 3rem;
  gap: 2rem;
}

/* ── Page heading ───────────────────────────────────── */
.page-heading {
  text-align: center;
}
.page-heading h1 {
  font-size: clamp(1.4rem, 4vw, 2rem);
  font-weight: 700;
  color: var(--text);
}
.page-heading p {
  margin-top: 0.4rem;
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ── Image card ─────────────────────────────────────── */
.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
}
.image-card__img-wrap {
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--surface-2);
  overflow: hidden;
}
.image-card__img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.image-card__meta {
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.image-card__info {
  flex: 1;
  min-width: 0;
}
.image-card__title {
  font-weight: 600;
  font-size: 0.9375rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.image-card__subtitle {
  color: var(--text-muted);
  font-size: 0.8125rem;
  margin-top: 0.125rem;
}
.image-card__actions {
  flex-shrink: 0;
}

/* ── Buttons ────────────────────────────────────────── */
button { cursor: pointer; font-family: inherit; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  line-height: 1;
  text-decoration: none;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn--danger {
  background: transparent;
  border-color: var(--danger);
  color: var(--danger);
}
.btn--danger:hover {
  background: rgba(224, 82, 82, 0.12);
}
.btn--danger:active {
  background: rgba(224, 82, 82, 0.2);
}

.btn--ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
}
.btn--ghost:hover {
  background: var(--surface-2);
  border-color: #3e4460;
}

.btn--filled-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn--filled-danger:hover {
  background: var(--danger-dark);
  border-color: var(--danger-dark);
}
.btn--filled-danger:active {
  background: #a83030;
}

/* ── Dialog ─────────────────────────────────────────── */
dialog {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  padding: 0;
  width: min(92vw, 420px);
  box-shadow: var(--shadow-lg);
  /* Closed by default; shown via JS .showModal() */
}
dialog::backdrop {
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(3px);
}

.dialog__header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.5rem 1.5rem 1rem;
}
.dialog__icon {
  flex-shrink: 0;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  background: rgba(224, 82, 82, 0.15);
  display: grid;
  place-items: center;
  color: var(--danger);
}
.dialog__icon svg { display: block; }

.dialog__title {
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.3;
  margin-top: 0.35rem;
}

.dialog__body {
  padding: 0 1.5rem 1.25rem;
  color: var(--text-muted);
  font-size: 0.9375rem;
  line-height: 1.6;
}
.dialog__body strong {
  color: var(--text);
  font-weight: 500;
}

.dialog__footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  padding: 1rem 1.5rem 1.5rem;
  border-top: 1px solid var(--border);
}

/* ── Footer ─────────────────────────────────────────── */
.site-footer {
  border-top: 1px solid var(--border);
  padding: 1rem 2rem;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.8125rem;
}

/* ── Reduced motion ─────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; }
}

/* ── Forced colors ──────────────────────────────────── */
@media (forced-colors: active) {
  .btn, dialog { border: 2px solid ButtonText; }
  dialog::backdrop { background: Canvas; }
}

/* ── Reflow / narrow viewports ──────────────────────── */
@media (max-width: 400px) {
  .dialog__footer { flex-direction: column-reverse; }
  .dialog__footer .btn { width: 100%; justify-content: center; }
  .site-header { padding: 0.75rem 1rem; }
}
